function shortestChains(start: string, end: string, words: string[]): string[][] {
  const unused = new Set(words);
  if (!unused.has(end)) return [];
  unused.delete(start);
  let level: string[][] = [[start]];
  const done: string[][] = [];
  while (level.length && !done.length) {
    const next: string[][] = [], usedNow = new Set<string>();
    for (const path of level) {
      const w = path[path.length - 1];
      for (let i = 0; i < w.length; i++) {
        for (let c = 97; c <= 122; c++) {
          const nw = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
          if (!unused.has(nw)) continue;
          const np = [...path, nw];
          if (nw === end) done.push(np); else next.push(np);
          usedNow.add(nw);
        }
      }
    }
    for (const w of usedNow) unused.delete(w);
    level = next;
  }
  return done;
}

