function shortestChains(start: string, end: string, words: string[]): string[][] {
  const unused = new Set(words);
  if (!unused.has(end)) return [];
  unused.delete(start);
  const parents = new Map<string, string[]>();
  let level = [start];
  while (level.length && !parents.has(end)) {
    const next: string[] = [];
    for (const w of level) {
      for (let i = 0; i < w.length; i++) {
        for (let c = 97; c <= 122; c++) {
          const nw = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
          if (!unused.has(nw)) continue;
          if (!parents.has(nw)) { parents.set(nw, []); next.push(nw); }
          parents.get(nw)!.push(w);
        }
      }
    }
    for (const w of next) unused.delete(w); // only after the whole level
    level = next;
  }
  if (!parents.has(end)) return [];
  const out: string[][] = [], path = [end];
  const back = (w: string): void => {
    if (w === start) { out.push([...path].reverse()); return; }
    for (const p of parents.get(w)!) { path.push(p); back(p); path.pop(); }
  };
  back(end);
  return out;
}

